import fs from 'node:fs';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
function clean(v){v=JSON.parse(JSON.stringify(v));function walk(x){if(!x||typeof x!=='object')return;for(const[k,w]of Object.entries(x)){if(typeof w==='string'&&w.startsWith('routing_'))x[k]='$transaction';else if(k==='expiresAt')x[k]='$time';else walk(w);}}if(v?.result?.content?.[0]?.text)try{v.result.content[0].text=JSON.parse(v.result.content[0].text)}catch{}walk(v);return v;}
const rows=[];for(const tool of ['liveRoutingPreviewAsync','liveRoutingApplyAsync']){const valid=tool.includes('Preview')?{trackRef:'track:track-1',arm:true}:{transactionId:'missing',confirmation:'apply',idempotencyKey:'apply-key'};const cases=[null,[],{},0,false,'x',valid,{...valid,extra:true}];for(const key of (tool.includes('Preview')?['trackRef','inputType','inputSubRouting','outputType','outputSubRouting','arm','monitoring']:Object.keys(valid))){const omitted={...valid};delete omitted[key];cases.push(omitted);for(const value of [null,[],{},false,true,0,1,'','auto','off','in',['auto'],{toString:1},'a'.repeat(257)])cases.push({...valid,[key]:value});}for(const args of cases){const host=new McpHost(new DeterministicLiveSimulator());let result;try{result=clean(await host[tool](1,args))}catch(e){result={error:e.message}}rows.push({tool,args,result});}}
const modes={arm:{arm:true},monitoring:{monitoring:'off'},input:{inputType:'No Input'},output:{outputType:'Main'},sub:{inputSubRouting:'2'},all:{inputType:'Ext. In',inputSubRouting:'2',outputType:'Main',outputSubRouting:'1/2',arm:true,monitoring:'off'}};
const scenarios=['normal','preview-cycle','apply-cycle','undo-cycle','expire','epoch','identity-edit','routing-edit','arm-edit','monitoring-edit','missing-identity','no-input','apply-before','apply-after','apply-refusal','apply-no-effect','apply-null','apply-read','apply-identity','apply-delayed','undo-before','undo-after','undo-refusal','undo-no-effect','undo-null','undo-read','undo-current-read','undo-edit','undo-identity','undo-moved','undo-ambiguous'];
const workflows=[];
for(const [mode,proposed]of Object.entries(modes))for(const scenario of scenarios){
 const sim=new DeterministicLiveSimulator(),calls=[],cache=new Map();let fault='',fired=false,afterInvoke=false,pendingSnapshot;const target=sim.state.tracks[0];const other=structuredClone(target);Object.assign(other,{ref:'track:other',name:'Other',objectIdentity:'simulator:track:other'});sim.state.tracks.push(other);if(scenario==='preview-cycle')target.routing.outputType=target.name;if(scenario==='missing-identity')delete target.objectIdentity;if(scenario==='no-input'){target.routing.inputType='No Input';target.routing.inputSubRouting=null;}
 function context(c){return c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null;}
 function readFault(){if(!fired&&((fault.endsWith('-read')&&afterInvoke)||fault==='undo-current-read')){fired=true;throw Error('injected authoritative read failure')}}
 function invoke(i,c){calls.push(clean({method:'invoke',invocation:i,context:context(c)}));const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(cache.has(key))return cache.get(key);if(!fired&&['before','refusal'].some(s=>fault.endsWith(s))){fired=true;throw fault.endsWith('refusal')?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):Error('injected operation failure')}
 const noEffect=!fired&&fault.endsWith('no-effect'),nullResult=!fired&&fault.endsWith('-null');if(fault==='apply-delayed'&&!fired)pendingSnapshot=structuredClone(sim.state);const result=noEffect?{changed:false}:sim.invoke(i);if(noEffect||nullResult)fired=true;cache.set(key,nullResult?null:result);afterInvoke=true;if(!fired&&fault==='apply-identity'){target.objectIdentity='other';fired=true}if(!fired&&fault.endsWith('after')){fired=true;throw Error('injected operation failure')}return nullResult?null:result;}
 const adapter={status:()=>sim.status(),snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),snapshotAsync:async(c,r)=>{calls.push(clean({method:'snapshot',request:r??null,context:context(c)}));readFault();if(pendingSnapshot){const old=pendingSnapshot;pendingSnapshot=undefined;fired=true;return old}return sim.snapshotAsync(c,r)},discoverAsync:async(r,c)=>{calls.push(clean({method:'discover',request:r,context:context(c)}));readFault();return sim.discoverAsync(r,c)},getAsync:async(r,c)=>{calls.push(clean({method:'get',reference:r,context:context(c)}));readFault();return sim.get(r)},invokeAsync:async(i,c)=>invoke(i,c),refreshStatusAsync:async c=>{calls.push(clean({method:'status',context:context(c)}));return sim.status()}};
 const host=new McpHost(adapter),results=[],states=[];const preview=await host.liveRoutingPreviewAsync(1,{trackRef:target.ref,...proposed});results.push(clean(preview));const body=JSON.parse(preview.result.content[0].text);const txid=body.transactionId;
 if(txid){const record=host.clipLifecycleTransactions.get(txid);async function perform(action,key){const args={transactionId:txid,confirmation:action,idempotencyKey:key};results.push(clean(action==='apply'?await host.liveRoutingApplyAsync(results.length+1,args):await host.liveUndoAsync(results.length+1,args)));states.push(clean(record))}
 if(scenario==='apply-cycle')sim.state.tracks[1].routing.outputType=sim.state.tracks[1].name;if(scenario==='expire')record.expiresAt=0;if(scenario==='epoch')sim.reconnect();if(scenario==='identity-edit')target.objectIdentity='other';if(scenario==='routing-edit')target.routing.outputType='other';if(scenario==='arm-edit')target.armed=true;if(scenario==='monitoring-edit')target.monitoringState='in';if(scenario.startsWith('apply-'))fault=scenario;
 for(const key of ['apply-key','other-key','apply-key'])await perform('apply',key);fault='';fired=false;afterInvoke=false;
 if(scenario==='undo-cycle')sim.state.tracks[1].routing.outputType=sim.state.tracks[1].name;if(scenario==='undo-edit'){const key=Object.keys(proposed)[0];if(key==='arm')target.armed=!target.armed;else if(key==='monitoring')target.monitoringState='in';else target.routing[key]='Manual';}
 if(scenario==='undo-identity')target.objectIdentity='other';if(scenario==='undo-moved'){target.ref='track:moved';sim.state.tracks.push(sim.state.tracks.shift())}if(scenario==='undo-ambiguous'){const extra=structuredClone(target);extra.ref='track:duplicate';sim.state.tracks.push(extra)}
 if(scenario.startsWith('undo-')&&!['undo-edit','undo-identity','undo-moved','undo-ambiguous','undo-cycle'].includes(scenario))fault=scenario;
 for(const key of ['undo-key','other-undo-key','undo-key'])await perform('undo',key);fault='';fired=false;afterInvoke=false;await perform('undo','new-undo-key');}
 workflows.push({mode,scenario,results,states,calls,target});
}
const graphs=[];for(let seed=0;seed<256;seed++){const tracks=Array.from({length:4},(_,i)=>({ref:'t'+i,name:'Track'+i,routing:{inputType:(seed>>(2*i)&1)?'Track'+((i+1)%4):'Ext. In',outputType:(seed>>(2*i+1)&1)?'Track'+((i+2)%4):'Main'}}));if(seed%17===0)tracks[3].name=tracks[1].name;const proposed=seed%2?{outputType:'Track'+(seed%4)}:{arm:true};const host=new McpHost(new DeterministicLiveSimulator());graphs.push({snapshot:{tracks},target:'t0',proposed,result:host.routingWouldCreateCycle({tracks},'t0',proposed)});}
fs.writeFileSync(new URL('host-routing-oracle.json',import.meta.url),JSON.stringify({rows,modes,workflows,graphs}));console.log({rows:rows.length,workflows:workflows.length,graphs:graphs.length});
